// 10 — Bar-chart race in Remotion + SVG. ALL DATA IS FICTIONAL, generated by a seeded random walk, labelled on screen.
import React from 'react';
import { AbsoluteFill, Audio, Easing, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';
const C = { ink: '#0B1020', ink2: '#141B33', cream: '#F4EFE6', mist: '#9AA3C7' };
const STUDIOS = [
  { name: 'Nebula Labs', color: '#7B61FF' }, { name: 'Kite Studio', color: '#FF6B5B' }, { name: 'Orbit Works', color: '#2EC4B6' },
  { name: 'Paper Moon', color: '#FFC857' }, { name: 'Tidal FX', color: '#6EC1FF' }, { name: 'Ember & Co.', color: '#FF9F68' },
  { name: 'Lumen House', color: '#C86BFA' }, { name: 'Quartz Motion', color: '#9BE564' },
];
// seeded fictional series: 29 quarterly points, 2019 Q1 .. 2026 Q1
let s = 20261026; const rnd = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
const Q = 29;
const DATA = STUDIOS.map((st, i) => { let v = 20 + rnd() * 40; const drift = 0.02 + rnd() * 0.09; const surge = Math.floor(rnd() * Q); const out: number[] = [];
  for (let q = 0; q < Q; q++) { v *= 1 + drift + (rnd() - 0.45) * 0.12 + (Math.abs(q - surge) < 3 ? 0.12 : 0); out.push(v); } return out; });
const sm = (x: number) => x * x * (3 - 2 * x);
const valueAt = (i: number, qf: number) => { const q0 = Math.max(0, Math.min(Q - 1, Math.floor(qf))), q1 = Math.min(Q - 1, q0 + 1); return DATA[i][q0] + (DATA[i][q1] - DATA[i][q0]) * sm(qf - q0); };
const rankAt = (qf: number) => { const v = STUDIOS.map((_, i) => valueAt(i, qf)); const order = v.map((x, i) => [x, i]).sort((a, b) => b[0] - a[0]).map((p) => p[1]); const r: number[] = []; order.forEach((idx, k) => (r[idx] = k)); return r; };
const fontCss = `
@font-face{font-family:'SG';font-weight:700;src:url(${staticFile('fonts/space-grotesk-latin-700-normal.woff2')})}
@font-face{font-family:'SG';font-weight:500;src:url(${staticFile('fonts/space-grotesk-latin-500-normal.woff2')})}
@font-face{font-family:'IN';font-weight:600;src:url(${staticFile('fonts/inter-latin-600-normal.woff2')})}
@font-face{font-family:'IN';font-weight:400;src:url(${staticFile('fonts/inter-latin-400-normal.woff2')})}
@font-face{font-family:'JB';font-weight:500;src:url(${staticFile('fonts/jetbrains-mono-latin-500-normal.woff2')})}`;
const RACE0 = 1.2, RACE1 = 10.6; // seconds
export const Race: React.FC = () => {
  const f = useCurrentFrame(); const { fps } = useVideoConfig(); const t = f / fps;
  const qf = interpolate(t, [RACE0, RACE1], [0, Q - 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.sin) });
  // smooth rank: box-filter the discrete rank over the previous 0.35 quarters-equivalent (stateless)
  const N = 8; const rk = STUDIOS.map(() => 0); for (let k = 0; k < N; k++) { const r = rankAt(Math.max(0, qf - k * 0.06)); r.forEach((v, i) => (rk[i] += v / N)); }
  const vals = STUDIOS.map((_, i) => valueAt(i, qf)); const maxV = Math.max(...vals);
  const X0 = 300, XW = 620, Y0 = 296, ROW = 72, BH = 52;
  const intro = spring({ frame: f, fps, config: { damping: 18, stiffness: 90 } });
  const year = 2019 + Math.floor(Math.round(qf) / 4), quarter = (Math.round(qf) % 4) + 1;
  // nice axis ticks
  const step = Math.pow(10, Math.floor(Math.log10(maxV / 3))); const tick = [1, 2, 5].map((m) => m * step).find((x) => maxV / x <= 5) || step * 10;
  const ticks = Array.from({ length: Math.floor(maxV / tick) + 1 }, (_, i) => i * tick);
  const leader = rk.indexOf(Math.min(...rk));
  return <AbsoluteFill style={{ background: `radial-gradient(circle at 30% 20%, #1A2246 0%, ${C.ink} 60%)` }}>
    <style>{fontCss}</style>
    <div style={{ position: 'absolute', left: 80, top: 70, right: 80, display: 'flex', justifyContent: 'space-between', font: '500 17px JB', letterSpacing: '.16em', color: C.mist }}>
      <span>MOTION STUDIO · Nº 10</span><span>REMOTION · SVG · TONE.JS</span></div>
    <div style={{ position: 'absolute', left: 78, top: 112, opacity: intro, transform: `translateY(${(1 - intro) * 20}px)` }}>
      <div style={{ font: '700 54px SG', letterSpacing: '-.025em', color: C.cream }}>Frames rendered, by studio</div>
      <div style={{ font: '400 22px IN', color: C.mist, marginTop: 6 }}>Millions of frames per quarter · <span style={{ color: '#FFC857' }}>illustrative example data, fictional studios</span></div></div>
    <svg width={1080} height={1080} style={{ position: 'absolute' }}>
      {ticks.map((v) => { const x = X0 + (v / maxV) * XW; return <g key={v} opacity={0.9 * intro}><line x1={x} x2={x} y1={Y0 - 26} y2={Y0 + ROW * 8 - 10} stroke="rgba(154,163,199,.18)" strokeDasharray="3 6" />
        <text x={x} y={Y0 - 36} fill={C.mist} fontFamily="JB" fontSize={15} textAnchor="middle">{v >= 1000 ? (v / 1000).toFixed(v % 1000 ? 1 : 0) + 'k' : Math.round(v)}</text></g>; })}
      {STUDIOS.map((st, i) => { const y = Y0 + rk[i] * ROW; const w = Math.max(8, (vals[i] / maxV) * XW) * interpolate(intro, [0, 1], [0, 1]);
        const lead = i === leader;
        return <g key={st.name} transform={`translate(0 ${y})`}>
          <text x={X0 - 22} y={BH / 2 + 8} textAnchor="end" fill={C.cream} fontFamily="IN" fontWeight={600} fontSize={24}>{st.name}</text>
          <rect x={X0} y={0} width={w} height={BH} rx={14} fill={st.color} opacity={0.95} />
          <rect x={X0} y={0} width={w} height={BH / 2} rx={14} fill="#fff" opacity={0.08} />
          {lead && <rect x={X0 - 6} y={-6} width={w + 12} height={BH + 12} rx={18} fill="none" stroke={st.color} strokeOpacity={0.45} strokeWidth={2} />}
          <text x={X0 + w + 14} y={BH / 2 + 8} fill={C.cream} fontFamily="JB" fontWeight={500} fontSize={20}>{Math.round(vals[i]).toLocaleString('en-US')}</text>
        </g>; })}
    </svg>
    <div style={{ position: 'absolute', right: 80, bottom: 70, textAlign: 'right' }}>
      <div style={{ font: '700 96px SG', letterSpacing: '-.04em', color: 'rgba(244,239,230,.92)', lineHeight: 1 }}>{year}</div>
      <div style={{ font: '500 22px JB', letterSpacing: '.2em', color: C.mist, marginTop: 6 }}>Q{quarter} · LEADER: <span style={{ color: STUDIOS[leader].color }}>{STUDIOS[leader].name.toUpperCase()}</span></div></div>
    <div style={{ position: 'absolute', left: 80, bottom: 76, font: '500 15px JB', letterSpacing: '.14em', color: 'rgba(154,163,199,.75)', lineHeight: 1.6 }}>
      EXAMPLE DATA · SEEDED RANDOM WALK<br />NOT REAL FIGURES</div>
    <Audio src={staticFile('music.wav')} />
  </AbsoluteFill>;
};
